update public.fields set verification_status='verified_against_standard', verification_quote='Umweltbezogene Anbietererklärungen müssen mit einer ergänzenden Erklärung verbunden sein, wenn die Aussage allein möglicherweise zu Missverständnissen führen kann. Eine Umweltaussage darf nur dann ohne ergänzende Erklärung erfolgen, wenn sie unter allen vorhersehbaren Umständen ohne Einschränkungen gültig ist. — printed p.16 (§5.6)', verification_note='md-verified 2026-09-05 (§5.6, printed p.16 derived) [VC] — the obligation is CONDITIONAL ("wenn die Aussage allein möglicherweise zu Missverständnissen führen kann"), so is_required=false is correct; gate REQ-04 makes it unconditional — STAGED', verified_at=now() where id='83910123-d427-4b04-8603-c30c6c5edacb' and verification_status not in ('verified_against_standard','corrected');

