update public.fields set verification_status='verified_against_standard', verification_quote='6.3.1 Vergleichende Aussagen müssen im Hinblick auf einen oder mehrere der folgenden Punkte bewertet werden: [...] Der Vergleich darf nur durchgeführt werden: - auf der Grundlage einer veröffentlichten Norm oder eines anerkannten Prüfverfahrens (siehe 6.4); und - in Bezug auf vergleichbare, gegenwärtige oder vor Kurzem in demselben Markt angebotene Produkte mit entsprechender Funktion von demselben oder einem anderen Anbieter. — printed p.22 (§6.3.1)', verification_note='md-verified 2026-09-05 (§6.3.1, printed p.22 derived) [VC] — the boolean records whether §6.3 applies at all; §7.5.2.1, §7.9.2.1, §7.10.2.4, §7.11.2.1 and §7.13.2.1 each declare their claim type comparative and route to §6.3', verified_at=now() where id='a15413f5-338d-4a10-8132-6eb222c5f908' and verification_status not in ('verified_against_standard','corrected');

-- comparison_basis
update public.fields set verification_status='verified_against_standard', verification_quote='6.3.1 Vergleichende Aussagen müssen im Hinblick auf einen oder mehrere der folgenden Punkte bewertet werden: a) vorheriges Verfahren einer Organisation; b) vorheriges Produkt einer Organisation; c) Verfahren einer anderen Organisation; oder d) Produkt einer anderen Organisation. — printed p.22 (§6.3.1)', verification_note='md-verified 2026-09-05 (§6.3.1 a) bis d), printed p.22 derived) [VC] — the four enum tokens map 1:1 onto the printed a)–d). CAVEAT: the source says "einen ODER MEHRERE der folgenden Punkte", the encoded field is single-select — STAGED', verified_at=now() where id='3f449e53-a3cc-454b-9c24-e05b946ae389' and verification_status not in ('verified_against_standard','corrected');

