update public.fields set verification_status='verified_against_standard', verification_quote='6.3.2 Vergleichende Aussagen, die Umweltaspekte des Produktlebensweges enthalten, müssen: a) in denselben Maßeinheiten gemessen und berechnet sein; b) auf derselben Funktionseinheit beruhen; und — printed p.22 (§6.3.2 a), b))', verification_note='md-verified 2026-09-05 (§6.3.2 b), printed p.22 derived; a) quoted with it because the encoded boolean is the only carrier for both) [VC] — "Funktionseinheit" is defined in §3.1.8 as "quantifizierter Nutzen eines Produktsystems für die Verwendung als Vergleichseinheit in einer Ökobilanzstudie"', verified_at=now() where id='366a3df2-454a-4962-862c-a5f84c483538' and verification_status not in ('verified_against_standard','corrected');

