-- method_selected
update public.fields set verification_status='verified_against_standard', verification_quote='Bewertungsverfahren und Verfahren zur Überprüfung von Aussagen müssen in der Reihenfolge Internationale Normen, anerkannte Normen internationaler Akzeptanz (diese können regionale oder nationale Normen sein) oder Verfahren von Industrie und Handel, die sich in einer Prüfung durch Dritte als gleichwertig erwiesen haben, durchgeführt werden. Existiert noch kein Verfahren, darf ein für Umweltfragen Verantwortlicher ein Verfahren entwickeln, das die übrigen Anforderungen von Abschnitt 6 erfüllt und anderen zur Überprüfung zur Verfügung steht. — printed p.23 (§6.4)', verification_note='md-verified 2026-09-05 (§6.4, printed p.23 derived) [VC] — all four enum tokens are printed: the three-step order of preference plus the claimant-developed fallback in the second sentence', verified_at=now() where id='935dd577-d759-47d1-a5e5-42b239611f7a' and verification_status not in ('verified_against_standard','corrected');

-- verifiable_without_confidential
