-- info_documented_min
update public.fields set verification_status='verified_against_standard', verification_quote='6.5.3 Die Mindestangaben, die nach 6.2 zu dokumentieren und aufzubewahren sind, müssen Folgendes enthalten: a) Angabe der angewendeten Norm oder des angewendeten Verfahrens; b) Dokumente/Unterlagen, falls die Überprüfung der Aussage nicht durch Prüfung des Endproduktes erfolgen kann; c) Prüfergebnisse für den Fall, dass diese zur Überprüfung der Aussage notwendig sind; d) bei Prüfung durch eine unabhängige Prüfstelle, deren Name und Adresse; e) Nachweis, dass die Aussage mit den Anforderungen von 5.7 h ) und 5.7 r ) übereinstimmt; — printed p.24 (§6.5.3 a) bis e))', verification_note='md-verified 2026-09-05 (§6.5.3 a) bis e), printed p.24 derived; f) and g) omitted for length and are quoted in the STAGED file) [VC] — the encoded description already names all seven items a)–g); the boolean is a single attestation over the whole list', verified_at=now() where id='ed9fccf1-b8a3-46e6-b73b-990fe61ea2cc' and verification_status not in ('verified_against_standard','corrected');

