-- recycled_content_pct
update public.fields set verification_status='verified_against_standard', verification_quote='7.8.4.1 Die Bewertung muss nach Abschnitt 6 erfolgen. Außerdem muss der Recyclatgehalt quantitativ als prozentualer Anteil, wie nachstehend berechnet, angegeben werden. Weil keine Verfahren für die direkte Bestimmung des Recyclatgehaltes in einem Produkt oder einer Verpackung verfügbar sind, muss die Masse des beim Recyclingverfahren erhaltenen Materials unter Berücksichtigung von Verlusten und sonstigen Resten verwendet werden. | $X(\%)=\frac{A}{P} \times 100$ — printed p.37 (§7.8.4.1)', verification_note='md-verified 2026-09-05 (§7.8.4.1, printed p.37 derived) [VC] — the encoded description also claims "als ganze Zahl fuer Drei-Pfeile-Symbol": that is §7.8.3.2 (p.36) "wobei $X$ der nach 7.8.4 berechnete, als ganze Zahl angegebene Recyclatgehalt ist" — printed, but only WHEN the Drei-Pfeile-Symbol is used; no gate enforces it — STAGED. derived value: engine output of EQ-02', verified_at=now() where id='fee3a082-4569-4438-9697-4b95e7a548f2' and verification_status not in ('verified_against_standard','corrected');

